void spade_model_run(const float *raw)
{
    spade_normalize(raw, SPADE_INPUT_STEPS, SPADE_INPUT_CHANNELS, level_center, level_scale, (spade_arena + 8192L), spade_mu, spade_sigma);
    spade_conv1d((spade_arena + 8192L), 256L, 4L, (spade_arena + 0L), 32L, w0_kernel, w0_bias, 3L, 1L, 2L);
    spade_batchnorm((spade_arena + 0L), 256L, 32L, (spade_arena + 0L), w1_scale, w1_offset);
    spade_relu((spade_arena + 0L), 8192L, (spade_arena + 0L));
    spade_conv1d((spade_arena + 0L), 256L, 32L, (spade_arena + 8192L), 32L, w3_kernel, w3_bias, 3L, 2L, 4L);
    spade_batchnorm((spade_arena + 8192L), 256L, 32L, (spade_arena + 8192L), w4_scale, w4_offset);
    spade_relu((spade_arena + 8192L), 8192L, (spade_arena + 8192L));
    spade_conv1d((spade_arena + 8192L), 256L, 32L, (spade_arena + 0L), 32L, w6_kernel, w6_bias, 3L, 4L, 8L);
    spade_batchnorm((spade_arena + 0L), 256L, 32L, (spade_arena + 0L), w7_scale, w7_offset);
    spade_relu((spade_arena + 0L), 8192L, (spade_arena + 0L));
    spade_conv1d((spade_arena + 0L), 256L, 32L, (spade_arena + 8192L), 32L, w9_kernel, w9_bias, 3L, 8L, 16L);
    spade_batchnorm((spade_arena + 8192L), 256L, 32L, (spade_arena + 8192L), w10_scale, w10_offset);
    spade_relu((spade_arena + 8192L), 8192L, (spade_arena + 8192L));
    spade_conv1d((spade_arena + 8192L), 256L, 32L, (spade_arena + 0L), 32L, w12_kernel, w12_bias, 3L, 16L, 32L);
    spade_batchnorm((spade_arena + 0L), 256L, 32L, (spade_arena + 0L), w13_scale, w13_offset);
    spade_relu((spade_arena + 0L), 8192L, (spade_arena + 0L));
    spade_conv1d((spade_arena + 0L), 256L, 32L, (spade_arena + 8192L), 32L, w15_kernel, w15_bias, 3L, 32L, 64L);
    spade_batchnorm((spade_arena + 8192L), 256L, 32L, (spade_arena + 8192L), w16_scale, w16_offset);
    spade_relu((spade_arena + 8192L), 8192L, (spade_arena + 8192L));
    spade_conv1d((spade_arena + 8192L), 256L, 32L, (spade_arena + 0L), 32L, w18_kernel, w18_bias, 3L, 64L, 128L);
    spade_batchnorm((spade_arena + 0L), 256L, 32L, (spade_arena + 0L), w19_scale, w19_offset);
    spade_relu((spade_arena + 0L), 8192L, (spade_arena + 0L));
    spade_dense((spade_arena + 8160L), 32L, (spade_arena + 8192L), 256L, w22_kernel, w22_bias);
}

const float *spade_model_output(void)
{
    return (spade_arena + 8192L);
}

const float *spade_model_mu(void)
{
    return spade_mu;
}

const float *spade_model_sigma(void)
{
    return spade_sigma;
}

int32_t spade_model_decide(void)
{
    return spade_decide((spade_arena + 8192L), SPADE_OUTPUT_LEN, 0.000000000e+00f, 0.000000000e+00f);
}
